CREATE TABLE IF NOT EXISTS students(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(120) NOT NULL UNIQUE,phone VARCHAR(20),department VARCHAR(80),semester INT,password_hash VARCHAR(100) NOT NULL,id_card MEDIUMTEXT,status ENUM('PENDING','VERIFIED','REJECTED') DEFAULT 'PENDING',role ENUM('STUDENT','ADMIN') DEFAULT 'STUDENT',token CHAR(36),created TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS books(id INT AUTO_INCREMENT PRIMARY KEY,title VARCHAR(200) NOT NULL,author VARCHAR(150),subject VARCHAR(100),semester INT,department VARCHAR(80),book_condition ENUM('NEW','GOOD','FAIR','WORN') DEFAULT 'GOOD',price DECIMAL(8,2) DEFAULT 0,type ENUM('SELL','EXCHANGE','BORROW') NOT NULL,availability ENUM('AVAILABLE','SOLD','EXCHANGED','BORROWED','REMOVED') DEFAULT 'AVAILABLE',cover MEDIUMTEXT,owner_id INT NOT NULL,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(owner_id) REFERENCES students(id),INDEX(availability,type));
CREATE TABLE IF NOT EXISTS requests(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,requester_id INT NOT NULL,type ENUM('SELL','EXCHANGE','BORROW') NOT NULL,status ENUM('PENDING','ACCEPTED','REJECTED') DEFAULT 'PENDING',created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(requester_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS borrowings(id INT AUTO_INCREMENT PRIMARY KEY,book_id INT NOT NULL,owner_id INT NOT NULL,borrower_id INT NOT NULL,borrow_date DATE NOT NULL,due_date DATE NOT NULL,returned BOOLEAN DEFAULT 0,remind2 BOOLEAN DEFAULT 0,remind1 BOOLEAN DEFAULT 0,FOREIGN KEY(book_id) REFERENCES books(id),FOREIGN KEY(owner_id) REFERENCES students(id),FOREIGN KEY(borrower_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS notifications(id INT AUTO_INCREMENT PRIMARY KEY,recipient_id INT NOT NULL,message VARCHAR(255) NOT NULL,is_read BOOLEAN DEFAULT 0,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(recipient_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS reviews(id INT AUTO_INCREMENT PRIMARY KEY,reviewer_id INT NOT NULL,reviewed_id INT NOT NULL,rating TINYINT NOT NULL,feedback VARCHAR(500),created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(reviewer_id,reviewed_id),FOREIGN KEY(reviewer_id) REFERENCES students(id),FOREIGN KEY(reviewed_id) REFERENCES students(id));
CREATE TABLE IF NOT EXISTS reports(id INT AUTO_INCREMENT PRIMARY KEY,reporter_id INT NOT NULL,book_id INT NOT NULL,reason VARCHAR(300) NOT NULL,resolved BOOLEAN DEFAULT 0,created TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(reporter_id) REFERENCES students(id),FOREIGN KEY(book_id) REFERENCES books(id));
